<div class="page-head"><div><h3>Daily entry</h3><p>One row per material + date, covering all tracking activities.</p></div><form class="month-form"><input type="month" name="month" value="<?= esc($month) ?>"><button class="primary">Apply</button></form></div><section class="panel form-panel"><form method="post" action="<?= base_url('daily-entries/save') ?>"><?= csrf_field() ?><div class="form-grid"><label>Material<select name="material_id" required><option value="">Select material</option><?php foreach($materials as $m): ?><option value="<?= $m['id'] ?>"><?= esc($m['code'].' — '.$m['description']) ?></option><?php endforeach; ?></select></label><label>Entry date<input type="date" name="entry_date" value="<?= date('Y-m-d') ?>" required></label><label>Receipt quantity<input type="number" step="0.00001" name="receipt_qty" value="0"></label><label>Receipt challan<input name="receipt_challan_no"></label><label>Issued quantity<input type="number" step="0.00001" name="issued_qty" value="0"></label><label>In-process rejection<input type="number" step="0.00001" name="in_process_rejection_qty" value="0"></label><label>In-process rejection reason<input name="in_process_rejection_reason"></label><label>Other rejection<input type="number" step="0.00001" name="other_rejection_qty" value="0"></label><label>Other rejection comment<input name="other_rejection_comment"></label><label>Transfer out<input type="number" step="0.00001" name="transfer_out_qty" value="0"></label><label>Transfer challan<input name="transfer_challan_no"></label><label>Production output<input type="number" step="0.00001" name="production_output_qty" value="0"></label><label>Production deviation reason<input name="production_deviation_reason"></label><label>Samples quantity<input type="number" step="0.00001" name="samples_qty" value="0"></label></div><button class="primary">Save daily entry</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Material</th><th>Receipt</th><th>Issue</th><th>Rejection</th><th>Transfer</th><th>Production</th><th>Samples</th><th>User</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= esc($r['entry_date']) ?></td><td><b><?= esc($r['code']) ?></b><small><?= esc($r['description']) ?></small></td><td><?= number_format($r['receipt_qty'],3) ?></td><td><?= number_format($r['issued_qty'],3) ?></td><td><?= number_format($r['in_process_rejection_qty']+$r['other_rejection_qty'],3) ?></td><td><?= number_format($r['transfer_out_qty'],3) ?></td><td><?= number_format($r['production_output_qty'],3) ?></td><td><?= number_format($r['samples_qty'],3) ?></td><td><?= esc($r['user_name']) ?></td><td><form method="post" action="<?= base_url('daily-entries/delete/'.$r['id']) ?>"><?= csrf_field() ?><button class="link">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>